INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 122601, 1, 0.029, 101, 1, 0, 160, 1.5, 110, 105, 0, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (2, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 122401, 3, 0.014, 102, 0, 0, 120, 2.5, 105, 111, 1, 2);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (3, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 122501, 2, 0.017, 103, 0, 1, 350, 2.5, 110, 105, 0, 3);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (4, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 107501, 3, 0.016, 104, 0, 0, 130, 1.5, 110, 105, 1, 4);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (5, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 107601, 1, 0.014, 105, 1, 0, 160, 2.5, 110, 105, 0, 5);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (6, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 107801, 2, 0.029, 106, 0, 1, 255, 3.5, 120, 103, 0, 6);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (7, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 110601, 1, 0.013, 107, 1, 0, 160, 3.5, 120, 103, 0, 7);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (8, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 110401, 2, 0.014, 108, 0, 1, 350, 2.5, 110, 103, 0, 8);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (9, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 110501, 3, 0.012, 109, 0, 0, 130, 1.5, 105, 100, 1, 9);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (10, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 115701, 1, 0.014, 110, 1, 0, 200, 2.5, 105, 103, 0, 10);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (11, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 113601, 2, 0.071, 111, 0, 1, 350, 2.5, 105, 103, 0, 11);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (12, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 107901, 3, 0.014, 112, 0, 0, 130, 1.5, 120, 103, 1, 12);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (13, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 108001, 2, 0.022, 113, 1, 0, 200, 1.5, 110, 105, 0, 13);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (14, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 110301, 1, 0.031, 114, 1, 0, 160, 2.5, 110, 108, 0, 14);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (15, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 107701, 1, 0.036, 115, 0, 0, 130, 0.5, 110, 105, 1, 15);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (16, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 113101, 2, 0.048, 116, 0, 1, 350, 3.5, 110, 95, 0, 16);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (17, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 113301, 3, 0.043, 117, 0, 0, 130, 1.5, 105, 105, 1, 17);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (18, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 113201, 2, 0.018, 118, 0, 0, 130, 1.5, 105, 95, 1, 18);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (19, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 117001, 2, 0.021, 119, 1, 0, 160, 2.5, 110, 108, 0, 19);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (20, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 113501, 1, 0.036, 120, 0, 1, 255, 2.5, 110, 105, 0, 20);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (21, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 113401, 3, 0.02, 121, 0, 1, 350, 2.5, 105, 105, 0, 21);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (22, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 110101, 1, 0.018, 122, 0, 0, 130, 2.5, 110, 105, 1, 22);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (23, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 110001, 3, 0.03, 123, 1, 0, 160, 3.5, 105, 111, 0, 23);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (24, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 117201, 1, 0.027, 124, 0, 0, 130, 1.5, 110, 103, 1, 24);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (25, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 117301, 2, 0.02, 125, 1, 0, 160, 3.5, 105, 108, 0, 25);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (26, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 117401, 3, 0.04, 126, 0, 1, 350, 2.5, 110, 105, 0, 26);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (27, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 117101, 1, 0.009, 127, 0, 1, 350, 3.5, 110, 105, 0, 27);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (28, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 122901, 1, 0.022, 128, 0, 1, 255, 3.5, 120, 105, 0, 28);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (29, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 122801, 3, 0.028, 129, 0, 0, 130, 2.5, 110, 105, 1, 29);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (30, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 122701, 2, 0.023, 130, 1, 0, 130, 3.5, 105, 108, 0, 30);
